let _markdown = "\n\nSetup [#setup]\n\n<FeedbackBlock id=\"68e83cd7e7ea2c22\" body=\"Define the i18n configurations in a file, we will import it with @/lib/i18n in this guide.\">\n  Define the i18n configurations in a file, we will import it with `@/lib/i18n` in this guide.\n</FeedbackBlock>\n\n```ts title=\"app/lib/i18n.ts\"\nimport { defineI18n } from 'fumadocs-core/i18n';\n\nexport const i18n = defineI18n({\n  defaultLanguage: 'en',\n  languages: ['cn', 'en'],\n});\n```\n\n> <FeedbackBlock id=\"f97b8076a44553cb\" body=\"See available options for i18n config.\">\n>   See [available options](/docs/headless/internationalization) for i18n config.\n> </FeedbackBlock>\n\nRouting [#routing]\n\n<FeedbackBlock id=\"055361d763885fed\" body=\"Add :lang prefix to all your pages.\">\n  Add `:lang` prefix to all your pages.\n</FeedbackBlock>\n\n```ts title=\"app/routes.ts\"\nimport { route, type RouteConfig } from '@react-router/dev/routes';\n\nexport default [\n  // [!code highlight:2]\n  route(':lang', 'routes/home.tsx'),\n  route(':lang/docs/*', 'docs/page.tsx'),\n  route('api/search', 'docs/search.ts'),\n] satisfies RouteConfig;\n```\n\nMake locale optional [#make-locale-optional]\n\n<FeedbackBlock id=\"204a5add05d8c125\" body=\"You can also use :lang? prefix, and update the i18n config:\">\n  You can also use `:lang?` prefix, and update the i18n config:\n</FeedbackBlock>\n\n<CodeBlockTabs defaultValue=\"app/lib/i18n.ts\">\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"app/lib/i18n.ts\">\n      app/lib/i18n.ts\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"app/routes.ts\">\n      app/routes.ts\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"app/lib/i18n.ts\">\n    ```ts\n    import { defineI18n } from 'fumadocs-core/i18n';\n\n    export const i18n = defineI18n({\n      defaultLanguage: 'en',\n      languages: ['cn', 'en'],\n      // [!code ++]\n      hideLocale: 'default-locale',\n    });\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"app/routes.ts\">\n    ```ts\n    import { route, type RouteConfig } from '@react-router/dev/routes';\n\n    export default [\n      // [!code highlight:2]\n      route(':lang?', 'routes/home.tsx'),\n      route(':lang?/docs/*', 'docs/page.tsx'),\n      route('api/search', 'docs/search.ts'),\n    ] satisfies RouteConfig;\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\nPages [#pages]\n\n<FeedbackBlock id=\"5eed5813d742d8b8\" body=\"Provide UI translations and other config to <RootProvider />, the English translations are used as fallbacks.\">\n  Provide UI translations and other config to `<RootProvider />`, the English translations are used as fallbacks.\n</FeedbackBlock>\n\n```tsx title=\"app/root.tsx\"\nimport { Links, Meta, Scripts, ScrollRestoration, useParams } from 'react-router';\nimport { RootProvider } from 'fumadocs-ui/provider/base';\nimport { ReactRouterProvider } from 'fumadocs-core/framework/react-router';\nimport { defineI18nUI } from 'fumadocs-ui/i18n';\nimport { i18n } from '@/lib/i18n';\nimport './app.css';\n\n// [!code ++:11]\nconst { provider } = defineI18nUI(i18n, {\n  translations: {\n    en: {\n      displayName: 'English',\n    },\n    cn: {\n      displayName: 'Chinese',\n      search: '搜尋文檔',\n    },\n  },\n});\n\nexport function Layout({ children }: { children: React.ReactNode }) {\n  const { lang = i18n.defaultLanguage } = useParams();\n\n  return (\n    <html lang=\"en\" suppressHydrationWarning>\n      <head>\n        <meta charSet=\"utf-8\" />\n        <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n        <Meta />\n        <Links />\n      </head>\n      <body className=\"flex flex-col min-h-screen\">\n        <ReactRouterProvider>\n          <RootProvider\n            // [!code ++]\n            i18n={provider(lang)}\n          >\n            {children}\n          </RootProvider>\n        </ReactRouterProvider>\n        <ScrollRestoration />\n        <Scripts />\n      </body>\n    </html>\n  );\n}\n```\n\nPass Locale [#pass-locale]\n\n<FeedbackBlock id=\"0b82611550540e1d\" body=\"Add locale parameter to baseOptions() and include i18n in props:\">\n  Add `locale` parameter to `baseOptions()` and include `i18n` in props:\n</FeedbackBlock>\n\n```tsx title=\"app/lib/layout.shared.tsx\"\nimport { i18n } from '@/lib/i18n';\nimport type { BaseLayoutProps } from 'fumadocs-ui/layouts/shared';\n\nexport function baseOptions(locale: string): BaseLayoutProps {\n  return {\n    i18n, // [!code ++]\n    // different props based on `locale`\n  };\n}\n```\n\n<FeedbackBlock id=\"3e651b8610b87b65\" body=\"Pass the locale to Fumadocs in your pages and layouts.\">\n  Pass the locale to Fumadocs in your pages and layouts.\n</FeedbackBlock>\n\n<CodeBlockTabs defaultValue=\"app/lib/source.ts\">\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"app/lib/source.ts\">\n      app/lib/source.ts\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"Home Layout\">\n      Home Layout\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"Docs Page\">\n      Docs Page\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"app/lib/source.ts\">\n    ```ts\n    import { i18n } from '@/lib/i18n';\n    import { loader } from 'fumadocs-core/source';\n\n    export const source = loader({\n      i18n, // [!code ++]\n      // other options\n    });\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"Home Layout\">\n    ```tsx  title=\"app/routes/home.tsx\"\n    import type { Route } from './+types/home';\n    import { HomeLayout } from 'fumadocs-ui/layouts/home';\n    import { baseOptions } from '@/lib/layout.shared';\n\n    export default function Home({ params }: Route.ComponentProps) {\n      return (\n        // [!code highlight]\n        <HomeLayout {...baseOptions(params.lang)}></HomeLayout>\n      );\n    }\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"Docs Page\">\n    ```tsx  title=\"app/docs/page.tsx\"\n    import type { Route } from './+types/page';\n    import { DocsLayout } from 'fumadocs-ui/layouts/docs';\n    import { source } from '@/lib/source';\n    import type * as PageTree from 'fumadocs-core/page-tree';\n    import { baseOptions } from '@/lib/layout.shared';\n\n    export async function loader({ params }: Route.LoaderArgs) {\n      const slugs = params['*'].split('/').filter((v) => v.length > 0);\n      // [!code --]\n      const page = source.getPage(slugs);\n      // [!code ++]\n      const page = source.getPage(slugs, params.lang);\n      if (!page) throw new Response('Not found', { status: 404 });\n\n      return {\n        path: page.path,\n        // [!code --]\n        tree: source.getPageTree(),\n        // [!code ++]\n        tree: source.getPageTree(params.lang),\n      };\n    }\n\n    export default function Page({ loaderData, params }: Route.ComponentProps) {\n      const { tree, path } = loaderData;\n\n      return (\n        <DocsLayout\n          // [!code highlight]\n          {...baseOptions(params.lang)}\n          tree={tree as PageTree.Root}\n        ></DocsLayout>\n      );\n    }\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\nSearch [#search]\n\n<FeedbackBlock id=\"45b21a9c840a57f5\" body=\"Configure i18n on your search solution.\">\n  Configure i18n on your search solution.\n</FeedbackBlock>\n\n<FeedbackBlock id=\"02c7dc6faba192b5\" body=\"Built-in Search (Orama): See Internationalization.Cloud Solutions (e.g. Algolia): They usually have official support for multilingual.\">\n  * **Built-in Search (Orama):** See [Internationalization](/docs/headless/search/orama#internationalization).\n  * **Cloud Solutions (e.g. Algolia):** They usually have official support for multilingual.\n</FeedbackBlock>\n\nWriting Documents [#writing-documents]\n\n<FeedbackBlock id=\"c0d8b07e16fa9e55\" body=\"See i18n routing to learn how to create pages for specific locales.\">\n  See [i18n routing](/docs/page-conventions#i18n-routing) to learn how to create pages for specific locales.\n</FeedbackBlock>\n\nNavigation [#navigation]\n\n<FeedbackBlock\n  id=\"297018bbd6566062\"\n  body=\"Fumadocs only handles navigation for its own layouts (e.g. sidebar).\nFor other places, you can use the useParams hook to get the locale from url.\"\n>\n  Fumadocs only handles navigation for its own layouts (e.g. sidebar).\n  For other places, you can use the `useParams` hook to get the locale from url.\n</FeedbackBlock>\n\n```tsx\nimport { Link, useParams } from 'react-router';\n\nconst { lang } = useParams();\n\n<Link to={`/${lang}/about`}>About Us</Link>;\n```\n\n<FeedbackBlock\n  id=\"8346696d779e3741\"\n  body=\"In addition, the fumadocs-core/dynamic-link component supports dynamic hrefs, you can use it to attend the locale prefix.\nIt is useful for Markdown/MDX content.\"\n>\n  In addition, the [`fumadocs-core/dynamic-link`](/docs/headless/components/link#dynamic-hrefs) component supports dynamic hrefs, you can use it to attend the locale prefix.\n  It is useful for Markdown/MDX content.\n</FeedbackBlock>\n\n```mdx title=\"content.mdx\"\nimport { DynamicLink } from 'fumadocs-core/dynamic-link';\n\n<DynamicLink href=\"/[lang]/another-page\">This is a link</DynamicLink>\n```\n";
